  const ALL_EXTRA_QUESTIONS = [...EXTRA_QUESTIONS, ...JULY_28_FINANCE_QUESTIONS];
  ALL_EXTRA_QUESTIONS.forEach(question => {
    const reasons = EXTRA_WRONG_REASONS[question.id] || [];
    const generatedReasons = Object.fromEntries(question.choices.flatMap((choice, index) => {
      const reason = reasons[index];
      return choice === question.answer || !reason ? [] : [[choice, reason]];
    }));
    question.choiceExplanations = { ...question.choiceExplanations, ...generatedReasons };
  });

